rules.suggestion:
确保UI操作在主线程执行：
```swift
// 危险 - 后台线程更新UI
URLSession.shared.dataTask(with: url) { data, _, _ in
    let result = parse(data)
    self.label.text = result  // 后台线程！
}.resume()

// 正确 - 切回主线程
URLSession.shared.dataTask(with: url) { data, _, _ in
    let result = parse(data)
    DispatchQueue.main.async {
        self.label.text = result
    }
}.resume()

// async/await中使用MainActor
@MainActor
func updateUI(result: String) {
    label.text = result
}
```
